class ExploreServletCoverageTest {

	private SailRepository store;
	private ExploreServlet servlet;
	private AtomicInteger queries;

	@BeforeEach
	void setUp() throws Exception {
		store = new SailRepository(new MemoryStore());
		store.init();
		queries = new AtomicInteger();
		Repository repository = new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public TupleQuery prepareTupleQuery(QueryLanguage language, String query, String base) {
						queries.incrementAndGet();
						return super.prepareTupleQuery(language, query, base);
					}

					@Override
					public void exportStatements(Resource subject, IRI predicate, Value object, boolean inferred,
							RDFHandler handler, Resource... contexts) {
						throw new AssertionError("Explore must query rather than export statements");
					}

					@Override
					public RepositoryResult<Statement> getStatements(Resource subject, IRI predicate, Value object,
							boolean inferred, Resource... contexts) {
						throw new AssertionError("Explore must query rather than read statements");
					}

					@Override
					public long size(Resource... contexts) {
						throw new AssertionError("Explore must query rather than call size");
					}
				};
			}
		};
		servlet = new ExploreServlet();
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("explore", "cookie-max-age", "300"));
	}

	@AfterEach
	void tearDown() {
		servlet.destroy();
		store.shutDown();
	}

	@Test
	void shellDoesNotQueryAndEveryDataRequestUsesOneSparqlQuery() throws Exception {
		var factory = store.getValueFactory();
		try (RepositoryConnection connection = store.getConnection()) {
			connection.add(factory.createIRI("urn:test:resource"), factory.createIRI("urn:test:predicate"),
					factory.createLiteral("value"));
		}
		MockHttpServletRequest shell = request("GET");
		servlet.service(shell, new MockHttpServletResponse());
		assertThat(queries).hasValue(0);

		MockHttpServletRequest listing = request("GET");
		listing.addParameter("section", "outgoing");
		listing.addParameter("kind", "rows");
		MockHttpServletResponse result = new MockHttpServletResponse();
		servlet.service(listing, result);
		assertThat(result.getContentAsString()).contains("\"type\":\"rows\"");
		assertThat(queries).hasValue(1);

		MockHttpServletRequest count = request("GET");
		count.addParameter("section", "outgoing");
		count.addParameter("kind", "count");
		count.addParameter("scope", "default");
		MockHttpServletResponse total = new MockHttpServletResponse();
		servlet.service(count, total);
		assertThat(total.getContentAsString()).contains("\"explore-count\":\"1\"");
		assertThat(queries).hasValue(2);
	}

	@Test
	void unknownWrapperUsesExposedDatasetWhileKnownMemoryStoreUsesPhysicalGraphs() {
		assertThat(ExploreGraphMode.physical(store, null, null)).isTrue();
		assertThat(ExploreGraphMode.physical(new RepositoryWrapper(store) {
		}, null, null)).isFalse();
		assertThat(ExploreGraphMode.physical(new RepositoryWrapper(store), null, null)).isTrue();
	}

	@Test
	void remoteModeUsesRepositoryConfigurationRatherThanUrl() {
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.getRepositoryConfig("memory"))
				.thenReturn(new RepositoryConfig("memory", new SailRepositoryConfig(new MemoryStoreConfig())));
		HTTPRepository remote = new HTTPRepository("http://example.invalid/repositories/memory");
		assertThat(ExploreGraphMode.physical(remote, manager, "memory")).isTrue();
		assertThat(ExploreGraphMode.physical(remote, manager, "proxy")).isFalse();
	}

	@Test
	void completedAndUnknownCancellationAreIdempotentButBlankIdsAreRejected() throws Exception {
		MockHttpServletRequest execution = request("GET");
		execution.addParameter("section", "outgoing");
		execution.addParameter("kind", "rows");
		execution.addParameter("query-request-id", "completed");
		servlet.service(execution, new MockHttpServletResponse());
		for (String id : List.of("completed", "completed", "unknown")) {
			MockHttpServletRequest cancellation = request("POST");
			cancellation.addParameter("action", "cancel-query");
			cancellation.addParameter("query-request-id", id);
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(cancellation, response);
			assertThat(response.getStatus()).as(id).isEqualTo(204);
		}
		MockHttpServletRequest blank = request("POST");
		blank.addParameter("action", "cancel-query");
		blank.addParameter("query-request-id", "  ");
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(blank, response);
		assertThat(response.getStatus()).isEqualTo(400);
	}

	@Test
	void cancellationAndExecutionShareTheExploreOperationKind() throws Exception {
		MockHttpServletRequest execution = request("GET");
		execution.addParameter("section", "outgoing");
		execution.addParameter("query-request-id", "id-1");
		var started = ExploreServlet.requestOperation(new WorkbenchRequest(null, execution, Map.of()));
		assertThat(started.kind()).isEqualTo("explore-query");
		assertThat(started.requestId()).isEqualTo("id-1");
		assertThat(started.cancellation()).isFalse();

		MockHttpServletRequest cancellation = request("POST");
		cancellation.addParameter("action", "cancel-query");
		cancellation.addParameter("query-request-id", "id-1");
		var stopped = ExploreServlet.requestOperation(new WorkbenchRequest(null, cancellation, Map.of()));
		assertThat(stopped.kind()).isEqualTo(started.kind());
		assertThat(stopped.requestId()).isEqualTo(started.requestId());
		assertThat(stopped.cancellation()).isTrue();
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(cancellation, response);
		assertThat(response.getStatus()).isEqualTo(204);
	}

	private static MockHttpServletRequest request(String method) {
		MockHttpServletRequest request = new MockHttpServletRequest(method, "/explore");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		request.addParameter("resource", "<urn:test:resource>");
		return request;
	}
}
